var(--cue-border)}.agency-catalog-preview::backdrop{background:#000c}.agency-catalog-preview__bar{position:sticky;top:0;z-index:10;display:flex;align-items:center;justify-content:space-between;padding:12px 20px;background:var(--cue-bg);border-bottom:1px solid var(--cue-border);font:10px monospace}@media(max-width:600px){.agency-catalog-editor__fields{grid-template-columns:1fr}.agency-catalog-editor__artist{align-items:start}.agency-catalog-preview__bar{padding:10px}}

.agency-catalog-editor{padding:36px 0}.agency-catalog-editor__heading{display:flex;align-items:flex-start;justify-content:space-between;gap:24px;margin-bottom:28px}.agency-catalog-editor h2{font-size:clamp(26px,3vw,40px);letter-spacing:-.04em;margin:8px 0}.agency-catalog-editor__status{flex-shrink:0;border:1px solid var(--cue-border);border-radius:var(--cue-radius-control);padding:8px 12px;font-size:11px;color:var(--cue-muted)}.agency-catalog-editor .agency-catalog-editor__group{padding:24px;margin:0 0 26px;border-radius:var(--cue-radius-panel);background:var(--cue-surface)}.agency-catalog-editor legend{font:700 12px/1.5 monospace;letter-spacing:.04em;padding:0 8px}.agency-catalog-editor__field{display:grid;gap:8px;margin:18px 0;font-size:12px}.agency-catalog-editor__optional{margin-top:20px;border-top:1px solid var(--cue-border);padding-top:18px}.agency-catalog-editor__optional summary{cursor:pointer;font-size:12px;min-height:28px}.agency-catalog-editor__artist{padding:16px 12px;margin-top:12px;border:1px solid var(--cue-border);border-radius:var(--cue-radius-control)}.agency-catalog-editor__artist.is-selected{border-color:color-mix(in srgb,var(--cue-toggle) 55%,var(--cue-border));background:color-mix(in srgb,var(--cue-toggle) 5%,var(--cue-surface))}.agency-catalog-editor__artist label{flex:1;cursor:pointer}.agency-catalog-editor__artist strong{font-size:13px}.agency-catalog-editor small{font-size:12px;line-height:1.5}.agency-catalog-editor__publish{padding:16px 0;cursor:pointer}.agency-catalog-editor__hint{border-left:3px solid #d6ab58;padding:10px 14px;background:color-mix(in srgb,#d6ab58 7%,var(--cue-surface))}.agency-catalog-editor__notice{border-left:3px solid var(--cue-toggle);padding:12px 16px;background:color-mix(in srgb,var(--cue-toggle) 7%,var(--cue-surface))}.agency-catalog-editor__error{border-left:3px solid #ed8989;padding:12px 16px;background:color-mix(in srgb,#ed8989 7%,var(--cue-surface))}.agency-catalog-editor button{min-height:44px;border-radius:var(--cue-radius-control)}.agency-catalog-editor input:not([type=checkbox]),.agency-catalog-editor textarea{border-radius:var(--cue-radius-control);font-size:14px;min-height:44px}.agency-catalog-editor__actions{margin-top:20px;gap:12px}.agency-catalog-editor__actions button:first-child{font-weight:700}@media(max-width:600px){.agency-catalog-editor__heading{flex-direction:column;gap:10px}.agency-catalog-editor .agency-catalog-editor__group{padding:18px 14px}.agency-catalog-editor__artist{flex-direction:column;align-items:stretch;gap:14px}.agency-catalog-editor__artist button{align-self:flex-start}.agency-catalog-editor__actions button{flex:1 1 140px}.agency-catalog-preview__bar{flex-wrap:wrap;gap:8px}}

.agency-catalog-editor__media-grid{display:grid;grid-template-columns:2fr 1fr;gap:24px;margin-top:28px}.agency-catalog-editor__media{min-width:0}.agency-catalog-editor__media h3{font-size:14px;letter-spacing:0;display:flex;align-items:center;gap:10px}.agency-catalog-editor__media h3 small{font-weight:400}.agency-catalog-editor__media-preview{aspect-ratio:16/9;border:1px solid var(--cue-border);border-radius:var(--cue-radius-control);background:var(--cue-bg);display:grid;place-items:center;overflow:hidden}.agency-catalog-editor__media-preview img{width:100%;height:100%;object-fit:cover}.agency-catalog-editor__media-preview.is-logo img{object-fit:contain;padding:20px;box-sizing:border-box}.agency-catalog-editor__media-preview span{padding:20px;color:var(--cue-muted);font-size:12px;text-align:center}.agency-catalog-editor__media-actions{display:flex;gap:10px;align-items:center}.agency-catalog-editor__media-picker{position:relative;display:inline-flex;align-items:center;justify-content:center;padding:0 14px;min-height:44px;cursor:pointer;border:1px solid var(--cue-border);border-radius:var(--cue-radius-control);font-size:12px}.agency-catalog-editor__media-picker input[type=file]{position:absolute;width:1px;height:1px;min-height:1px;padding:0;border:0;overflow:hidden;clip-path:inset(50%)}.agency-catalog-editor__media-picker:focus-within{outline:2px solid var(--cue-toggle);outline-offset:3px}fieldset:disabled .agency-catalog-editor__media-picker{opacity:.5;cursor:wait}@media(max-width:600px){.agency-catalog-editor__media-grid{grid-template-columns:1fr}}
